css:
body :where([data-bz-node="hc"]) .bz-block{padding:0}
body :where([data-bz-node="hc"]) .bz-container{padding:0;max-width:none}
body [data-bz-node="hc"]>.bz-container{padding-inline:0}

body [data-bz-node="hc-h"] .bz-eyebrow{font:700 10.5px/1.4 var(--font-body);letter-spacing:.22em;text-transform:uppercase;color:#6b6b6a;margin:0 0 14px}
body [data-bz-node="hc-h"] h2{font:700 36px/1.08 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0}
body [data-bz-node="hc-h"] h2:empty{display:none}
body [data-bz-node="hc-intro"] .bz-text{max-width:760px;margin-top:22px}
body [data-bz-node="hc-intro"] p{font:400 13.5px/25px var(--font-body);color:var(--ink);margin:0;margin:0 0 14px}
body [data-bz-node="hc-intro"] p:last-child{margin:0}
body [data-bz-node="hc-intro"] a{color:var(--accent);text-decoration:none}

body [data-bz-node="hc"]{background:#fff;padding:96px 0}
body [data-bz-node="hc"]>.bz-container{max-width:var(--container)}
body [data-bz-node="hc-grid"]{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr));gap:24px;margin-top:40px;align-items:stretch}
body [data-bz-node="hc-grid"]>.bz-col{grid-column:auto}
body [data-bz-node="hc-card"],body [data-bz-node="hc-dark"]{display:flex;flex-direction:column;padding:32px 32px 34px;box-sizing:border-box}
body [data-bz-node="hc-card"]{background:#fff;border:1px solid #e4e4e2}
body [data-bz-node="hc-dark"]{background:#2a2723}
body [data-bz-node="hc-ct"] h3{font:700 15px/1.35 var(--font-heading);text-transform:uppercase;color:var(--ink);margin:0 0 20px}
body [data-bz-node^="hc-day-"]{display:block;margin-bottom:6px}
body [data-bz-node^="hc-day-"] p{position:relative;padding-left:26px;font:400 12.5px/1.6 var(--font-body);color:#444;margin:0}
body [data-bz-node^="hc-day-"] p::before{content:"";position:absolute;left:0;top:2px;width:14px;height:14px;background:var(--ink);-webkit-mask:url(/icons/clock.svg) center/14px no-repeat;mask:url(/icons/clock.svg) center/14px no-repeat}
body [data-bz-node="hc-dt"] h3{font:700 15px/1.35 var(--font-heading);text-transform:uppercase;color:#fff;margin:0 0 20px}
body [data-bz-node="hc-dtext"] p{font:400 12.5px/1.75 var(--font-body);color:rgba(255,255,255,.88);margin:0}
body [data-bz-node="hc-dcta"]{margin-top:auto;padding-top:22px}
body [data-bz-node="hc-dcta"] .bz-btns{margin:0}
body [data-bz-node="hc-dcta"] .bz-btn{display:inline-flex;align-items:center;justify-content:center;height:44px;padding:0 24px;border:0;border-radius:3px;background:#fff;color:var(--ink);font:700 10.5px/1 var(--font-body);letter-spacing:.16em;text-transform:uppercase;text-decoration:none;gap:10px}
body [data-bz-node="hc-dcta"] .bz-btn::before{content:"";width:13px;height:13px;background:var(--ink);-webkit-mask:url(/icons/phone.svg) center/13px no-repeat;mask:url(/icons/phone.svg) center/13px no-repeat}
body [data-bz-node="hc-dcta"] .bz-btn:hover{background:#ececec}
@media (max-width:1100px){body [data-bz-node="hc"]{padding:64px 24px}body [data-bz-node="hc-h"] h2{font-size:30px}}
@media (max-width:640px){body [data-bz-node="hc"]{padding:48px 20px}body [data-bz-node="hc-h"] h2{font-size:26px}body [data-bz-node="hc-grid"]{gap:16px}}
